begin;
with j as (select * from jsonb_to_recordset($law7d0023$[{"code_id":"BK_RF","article_number":"20","version_date":"1998-07-31","article_text":"1. Код классификации доходов бюджетов Российской Федерации состоит из:\n\n1)  кода главного администратора доходов бюджета;\n\n2)  кода вида доходов;\n\n3)  кода подвида доходов;\n\n4)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. (Пункт утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n3. Код вида доходов включает группу,  подгруппу,  статью,  подстатью и элемент дохода.\n\n4. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами доходов бюджетов являются:\n\n1)  налоговые и неналоговые доходы:\n\nналоги на прибыль,  доходы;\n\nабзац; (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nналоги на товары (работы,  услуги) ,  реализуемые на территории Российской Федерации;\n\nналоги на товары,  ввозимые на территорию Российской Федерации;\n\nналоги на совокупный доход;\n\nналоги на имущество;\n\nналоги,  сборы и регулярные платежи за пользование природными ресурсами;\n\nгосударственная пошлина;\n\nзадолженность и перерасчеты по отмененным налогам,  сборам и иным обязательным платежам;\n\nстраховые взносы на обязательное социальное страхование; (Дополнение абзацем - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nдоходы от внешнеэкономической деятельности;\n\nдоходы от использования имущества,  находящегося в государственной и муниципальной собственности;\n\nплатежи при пользовании природными ресурсами;\n\nдоходы от оказания платных услуг и компенсации затрат государства;\n\nдоходы от продажи материальных и нематериальных активов;\n\nадминистративные платежи и сборы;\n\nштрафы,  санкции,  возмещение ущерба;\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпоступления (перечисления)  по урегулированию расчетов между бюджетами бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\nпрочие неналоговые доходы;\n\n2)  безвозмездные поступления:\n\nбезвозмездные поступления от нерезидентов;\n\nбезвозмездные поступления от других бюджетов бюджетной системы Российской Федерации;\n\nбезвозмездные поступления от государственных (муниципальных)  организаций;\n\nбезвозмездные поступления от негосударственных организаций;\n\nбезвозмездные поступления от наднациональных организаций;\n\nпоступления (перечисления)  для осуществления возврата (зачета)  излишне уплаченных или излишне взысканных сумм налогов,  сборов и иных платежей,  а также сумм процентов за несвоевременное осуществление такого возврата и процентов,  начисленных на излишне взысканные суммы; (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\nдоходы бюджетов бюджетной системы Российской Федерации от возврата остатков субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  прошлых лет; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nвозврат остатков субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  прошлых лет; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпрочие безвозмездные поступления.\n\n5. Доходы,  указанные в абзацах втором,  четвертом - десятом подпункта 1 пункта 4 настоящей статьи,  являются налоговыми доходами бюджетов. Доходы,  указанные в абзацах одиннадцатом - двадцать втором подпункта 1 пункта 4 настоящей статьи,  являются неналоговыми доходами бюджетов. (В редакции федеральных законов от 24.07.2009 № 213-ФЗ; от 07.05.2013 № 104-ФЗ)\n\n6. Единый для бюджетов бюджетной системы Российской Федерации перечень статей и подстатей доходов бюджетов утверждается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце первом настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых либо изменение действующих источников доходов федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов и местных бюджетов. (Дополнение абзацем - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\n7. Код элемента доходов устанавливается в зависимости от полномочия по установлению и нормативному правовому регулированию налогов,  сборов и иных обязательных платежей,  других доходов бюджетов бюджетной системы Российской Федерации,  а также в зависимости от наличия прав требования к плательщикам по неналоговым доходам и безвозмездным поступлениям и соответствует бюджету бюджетной системы Российской Федерации.\n\n8. Едиными для бюджетов бюджетной системы Российской Федерации элементами доходов являются:\n\n1)  федеральный бюджет;\n\n2)  бюджеты субъектов Российской Федерации;\n\n3)  бюджеты муниципальных районов;\n\n31)  бюджеты муниципальных округов; (Дополнение подпунктом - Федеральный закон от 01.10.2020 № 311-ФЗ)\n\n4)  бюджеты городских округов;\n\n41)  бюджеты городских округов с внутригородским делением; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n5)  бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n6)  бюджеты городских поселений; (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n61)  бюджеты сельских поселений; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n62)  бюджеты внутригородских районов; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n7)  бюджет Фонда пенсионного и социального страхования Российской Федерации; (В редакции  Федерального закона от 14.07.2022 № 264-ФЗ)\n\n8)  (Подпункт утратил силу  - Федеральный закон от 14.07.2022 № 264-ФЗ)\n\n9)  бюджет Федерального фонда обязательного медицинского страхования;\n\n10)  бюджеты территориальных фондов обязательного медицинского страхования.\n\n9. Для детализации поступлений по кодам классификации доходов применяется код подвида доходов.\n\nМинистерство финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса утверждает: (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nобщие требования к порядку формирования перечня кодов подвидов доходов бюджетов бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\nперечень кодов подвидов по видам доходов,  главными администраторами которых являются органы государственной власти (государственные органы)  Российской Федерации,  Центральный банк Российской Федерации,  органы управления государственными внебюджетными фондами Российской Федерации и (или)  находящиеся в их ведении казенные учреждения,  иные организации,  наделенные полномочиями главного администратора доходов федерального бюджета. (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце четвертом настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых либо изменение действующих источников доходов федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов и местных бюджетов в связи с принятием федеральных законов,  регулирующих вопросы установления нормативов распределения доходов между бюджетами бюджетной системы Российской Федерации. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nФинансовый орган субъекта Российской Федерации утверждает перечень кодов подвидов по видам доходов,  главными администраторами которых являются органы государственной власти субъектов Российской Федерации,  органы управления территориальными государственными внебюджетными фондами и (или)  находящиеся в их ведении казенные учреждения. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nФинансовый орган муниципального образования утверждает перечень кодов подвидов по видам доходов,  главными администраторами которых являются органы местного самоуправления и (или)  находящиеся в их ведении казенные учреждения. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 20. Классификация доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22efb538f3c7ed69dea9c6468ddd5c8ba9323356e5efd7bee4586610d88b521a"},{"code_id":"BK_RF","article_number":"21","version_date":"1998-07-31","article_text":"1. Код классификации расходов бюджетов состоит из:\n\n1)  кода главного распорядителя бюджетных средств;\n\n2)  кода раздела,  подраздела,  целевой статьи и вида расходов;\n\n3)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. Перечень главных распорядителей средств федерального бюджета,  бюджета субъекта Российской Федерации,  бюджетов государственных внебюджетных фондов,  местного бюджета устанавливается законом (решением)  о соответствующем бюджете в составе ведомственной структуры расходов.\n\n3. Едиными для бюджетов бюджетной системы Российской Федерации разделами и подразделами классификации расходов бюджетов являются:\n\n1)  общегосударственные вопросы:\n\nфункционирование Президента Российской Федерации;\n\nфункционирование высшего должностного лица субъекта Российской Федерации и муниципального образования;\n\nфункционирование законодательных (представительных)  органов государственной власти и представительных органов муниципальных образований;\n\nфункционирование  Правительства  Российской Федерации,  высших исполнительных органов субъектов Российской Федерации,  местных администраций; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nсудебная система;\n\nобеспечение деятельности финансовых,  налоговых и таможенных органов и органов финансового (финансово-бюджетного)  надзора;\n\nобеспечение проведения выборов и референдумов;\n\nмеждународные отношения и международное сотрудничество;\n\nгосударственный материальный резерв;\n\nфундаментальные исследования;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nрезервные фонды;\n\nприкладные научные исследования в области общегосударственных вопросов;\n\nдругие общегосударственные вопросы;\n\n2)  национальная оборона:\n\nВооруженные Силы Российской Федерации;\n\nредакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 21. Классификация расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"48dbe8c06e6d873f6ca0122b25c054532b4c3a8254d92cc03d2dd6fd5d766384"},{"code_id":"BK_RF","article_number":"22","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 22.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"}]$law7d0023$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
